19	/**
20	 * AuthService — Deliverable 1 §5.2 ("Users and Security").
21	 * Operations: authenticate(username, password) : Session, verifyTOTP(userId, code), validateSession(token),
22	 * authorize(userId, permission). This is the "Auth Gateway: TOTP, Authenticator, Authorization" box of §5.3.2.
23	 * TD-1 (3): "Remember this device for 30 days" — a remembered device signs in with username + password only; the
24	 * 6-digit code is required again on a new device or after 30 days (A-39). Still meets NFR Security (TD-1).
25	 */
26	@Service
27	public class AuthService {
28	    private static final SecureRandom RNG = new SecureRandom();
29	
30	    private final UserRepository users;
31	    private final SessionRepository sessions;
32	    private final TrustedDeviceRepository trustedDevices;
33	    private final PasswordHasher hasher;
34	    private final Duration sessionLifetime;
35	    private final Duration rememberFor;
36	
37	    public AuthService(UserRepository users, SessionRepository sessions, TrustedDeviceRepository trustedDevices,
38	                       PasswordHasher hasher,
39	                       @Value("${cometfit.session-hours}") long sessionHours,
40	                       @Value("${cometfit.remember-device-days:30}") long rememberDays) {
41	        this.users = users;
42	        this.sessions = sessions;
43	        this.trustedDevices = trustedDevices;
44	        this.hasher = hasher;
45	        this.sessionLifetime = Duration.ofHours(sessionHours);
46	        this.rememberFor = Duration.ofDays(rememberDays);
47	    }
48	
49	    /**
50	     * Result of a sign-in. {@code deviceToken} / {@code trustedUntil} are set only when the student asked to remember
51	     * this device and passed the TOTP check in this call (TD-1 (3)). {@code rememberedDevice} = the code was skipped.
52	     */
53	    public record LoginResult(Session session, String deviceToken, Instant trustedUntil, boolean rememberedDevice) {}
54	
55	    /**
56	     * authenticate(username, password) : Session. Because the NFR makes TOTP mandatory for every user,
57	     * a Session is only created after {@link #verifyTOTP} also succeeds, so the TOTP code is passed in the
58	     * same call (A-6). One generic error message is used so usernames cannot be probed.
59	     */
60	    @Transactional
61	    public Session authenticate(String username, String password, String totpCode) {
62	        return login(username, password, totpCode, false, null).session();
63	    }
64	
65	    /**
66	     * Sign-in with TD-1 (3). The password is always required. The TOTP code is skipped only when {@code deviceToken}
67	     * belongs to this user and is less than 30 days old; otherwise the code must be valid. Every failure gives the
68	     * same message (A-31), so the response never tells whether the password alone was right.
69	     * A remembered sign-in does not extend the 30 days (TD-1: "required again ... after 30 days").
70	     */
71	    @Transactional
72	    public LoginResult login(String username, String password, String totpCode, boolean rememberDevice,
73	                             String deviceToken) {
74	        User user = users.findByUsernameIgnoreCase(username == null ? "" : username.trim())
75	                .filter(u -> password != null && hasher.matches(password, u.getPasswordHash()))
76	                .orElseThrow(() -> ApiException.unauthorized("Invalid username, password or code"));
77	        Instant now = Instant.now();
78	
79	        boolean remembered = isTrusted(user.getUserId(), deviceToken, now);
80	        String newDeviceToken = null;
81	        Instant trustedUntil = null;
82	        if (!remembered) {
83	            if (!verifyTOTP(user.getUserId(), totpCode)) {
84	                throw ApiException.unauthorized("Invalid username, password or code");
85	            }
86	            if (rememberDevice) {
87	                newDeviceToken = randomHex();
88	                trustedUntil = now.plus(rememberFor);
89	                trustedDevices.save(new TrustedDevice(user.getUserId(), sha256(newDeviceToken), now, trustedUntil));
90	            }
91	        }
92	        Session session = sessions.save(new Session(randomHex(), user, now, now.plus(sessionLifetime)));
93	        return new LoginResult(session, newDeviceToken, trustedUntil, remembered);
94	    }
95	
96	    private boolean isTrusted(Long userId, String deviceToken, Instant now) {
97	        if (deviceToken == null || deviceToken.isBlank()) return false;
98	        return trustedDevices.findByTokenHash(sha256(deviceToken.trim()))
99	                .filter(t -> t.getUserId().equals(userId) && !t.isExpired(now))
100	                .isPresent();
101	    }
102	
103	    /** Forget every remembered device of a user (used when the password changes; A-39). */
104	    @Transactional
105	    public void forgetTrustedDevices(Long userId) {
106	        trustedDevices.deleteByUserId(userId);
107	    }
108	
109	    private static String randomHex() {
110	        byte[] t = new byte[32];
111	        RNG.nextBytes(t);
112	        return HexFormat.of().formatHex(t);
113	    }
114	
115	    static String sha256(String s) {
116	        try {
117	            return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));
118	        } catch (NoSuchAlgorithmException e) {
119	            throw new IllegalStateException(e);
120	        }
121	    }
122	
123	    /** verifyTOTP(userId, code) : boolean. */
124	    @Transactional(readOnly = true)
125	    public boolean verifyTOTP(Long userId, String code) {
126	        return users.findById(userId).map(u -> Totp.verify(u.getTotpSecret(), code, Instant.now())).orElse(false);
127	    }
128	
129	    /** validateSession(token) : boolean. */
130	    @Transactional(readOnly = true)
131	    public boolean validateSession(String token) {
132	        return findValid(token).isPresent();
133	    }
134	
135	    /** Returns the user behind a valid session (used by BaseController.requireSession). */
136	    @Transactional(readOnly = true)
137	    public User userForToken(String token) {
138	        return findValid(token).map(Session::getUser)
139	                .orElseThrow(() -> ApiException.unauthorized("Session missing or expired; please log in again"));
140	    }
141	
142	    /** authorize(userId, permission) : boolean — checks the backend permissions list. */
143	    @Transactional(readOnly = true)
144	    public boolean authorize(Long userId, String permission) {
145	        return users.findById(userId).map(u -> switch (u) {
146	            case Developer d -> d.hasPermission(permission);
147	            case Student s -> Permissions.STUDENT_DEFAULT.contains(permission);
148	            default -> false;
149	        }).orElse(false);
150	    }
151	
152	    @Transactional
153	    public void logout(String token) {
154	        if (token != null) sessions.deleteById(token);
155	    }
156	
157	    private Optional<Session> findValid(String token) {
158	        if (token == null || token.isBlank()) return Optional.empty();
159	        return sessions.findById(token).filter(s -> !s.isExpired());
160	    }
161	
162	    @Scheduled(fixedDelay = 3_600_000)
163	    public void purgeExpiredSessions() {
164	        sessions.deleteExpired(Instant.now());
165	        trustedDevices.deleteExpired(Instant.now());
166	    }
167	}
