1	package cometfit.security;
2	
3	import java.util.List;
4	
5	import org.springframework.stereotype.Service;
6	import org.springframework.transaction.annotation.Transactional;
7	
8	import cometfit.api.ApiException;
9	import cometfit.domain.ConsentSettings;
10	import cometfit.domain.ConsentSettingsRepository;
11	import cometfit.domain.PointAccount;
12	import cometfit.domain.PointAccountRepository;
13	
14	/**
15	 * Creates accounts. The spec has "Log In (Password + TOTP)" in every use case but no sign-up use case;
16	 * self-registration for students is A-3. Each new Student gets its 1 ConsentSettings and 1 PointAccount
17	 * (§5.2 multiplicities "configures 1", "owns 1"). Developers are created by seed/config only (A-14).
18	 */
19	@Service
20	public class AccountService {
21	    public static final String ISSUER = "CometFit";
22	
23	    private final UserRepository users;
24	    private final PasswordHasher hasher;
25	    private final ConsentSettingsRepository consents;
26	    private final PointAccountRepository points;
27	
28	    public AccountService(UserRepository users, PasswordHasher hasher,
29	                          ConsentSettingsRepository consents, PointAccountRepository points) {
30	        this.users = users;
31	        this.hasher = hasher;
32	        this.consents = consents;
33	        this.points = points;
34	    }
35	
36	    public record Registration(User user, String totpSecret, String otpauthUri) {}
37	
38	    @Transactional
39	    public Registration registerStudent(String username, String password, String email, String displayName) {
40	        return registerStudent(username, password, email, displayName, Totp.newSecret());
41	    }
42	
43	    @Transactional
44	    public Registration registerStudent(String username, String password, String email, String displayName,
45	                                        String totpSecret) {
46	        validate(username, password, email);
47	        Student s = new Student();
48	        fill(s, username, password, email, displayName, totpSecret);
49	        s = users.save(s);
50	        consents.save(new ConsentSettings(s.getUserId()));
51	        points.save(new PointAccount(s.getUserId()));
52	        return new Registration(s, totpSecret, Totp.otpauthUri(ISSUER, s.getUsername(), totpSecret));
53	    }
54	
55	    @Transactional
56	    public Registration createDeveloper(String username, String password, String email, String displayName,
57	                                        String adminRole, List<String> permissions, String totpSecret) {
58	        validate(username, password, email);
59	        Developer d = new Developer();
60	        fill(d, username, password, email, displayName, totpSecret);
61	        d.setAdminRole(adminRole);
62	        d.setPermissions(permissions);
63	        d = users.save(d);
64	        return new Registration(d, totpSecret, Totp.otpauthUri(ISSUER, d.getUsername(), totpSecret));
65	    }
66	
67	    private void fill(User u, String username, String password, String email, String displayName, String secret) {
68	        u.setUsername(username.trim());
69	        u.setPasswordHash(hasher.hash(password));
70	        u.setEmail(email.trim());
71	        u.setDisplayName(displayName == null || displayName.isBlank() ? username.trim() : displayName.trim());
72	        u.setTotpSecret(secret);
