  if (!cond) failures++;
}
async function login(username, secret) {
  const r = await call('POST', '/api/auth/login', null, { username, password: PASSWORD, totpCode: totp(secret) });
  check(`login ${username} (password + TOTP)`, r.status === 200, `HTTP ${r.status}`);
