1	// Shared UI kit for the CometFit mobile client (NFR Usability: simple, readable screens).
2	// Visual design: spec/03-team-decisions/TD-4.md — follows the team's Figma prototype in spec/05-ui-prototype/
3	// (dark green, orange accent, blue for water, warm off-white background, white rounded cards, headers with a
4	// subtitle and an initials avatar, bottom tab bar). Supersedes A-32. Exact hex values are read off the PNGs (A-42).
5	import React from 'react';
6	import {
7	  ActivityIndicator, Pressable, StyleSheet, Switch, Text, TextInput, TextInputProps, View, ViewStyle,
8	} from 'react-native';
9	
10	export const colors = {
11	  // TD-4 palette (prototype PNGs)
12	  bg: '#F6F6F1',          // warm off-white background
13	  card: '#FFFFFF',
14	  text: '#1C1C1A',
15	  heading: '#1D4B35',     // dark green titles / brand
16	  muted: '#6B6E68',
17	  primary: '#1D4B35',     // dark green: streak card, "+ Log exercise", active tab text
18	  primaryText: '#FFFFFF',
19	  accent: '#EF8E3A',      // orange: "Check in at UREC", streak bar
20	  accentText: '#1D4B35',
21	  food: '#B5561D',        // food calories (orange-brown)
22	  foodBg: '#FDF1E6',
23	  water: '#2F6FED',       // water ml (blue)
24	  waterBg: '#EAF1FD',
25	  soft: '#E4ECE2',        // light green: avatar, active tab pill, "You" row
26	  chip: '#EEEEEA',        // neutral grey chips / inputs
27	  chipActive: '#1C1C1A',  // black "Today" segment
28	  border: '#E6E6E0',
29	  good: '#1D7A3E',
30	  warn: '#9A5B00',
31	  warnBg: '#FFF4E0',
32	  bad: '#B3362B',
33	  badBg: '#FCECEA',
34	  infoBg: '#EAF1FD',
35	  track: '#ECECE6',
36	};
37	
38	export function Card({ title, right, children, style }: { title?: string; right?: string; children: React.ReactNode; style?: ViewStyle }) {
39	  return (
40	    <View style={[s.card, style]}>
41	      {title ? (
42	        <View style={s.cardHead}>
43	          <Text style={s.cardTitle}>{title}</Text>
44	          {right ? <Text style={s.muted}>{right}</Text> : null}
45	        </View>
46	      ) : null}
47	      {children}
48	    </View>
49	  );
50	}
51	
52	export type ButtonKind = 'primary' | 'secondary' | 'danger' | 'accent' | 'food' | 'water' | 'outlineDanger';
53	
54	export function Button({
55	  label, onPress, kind = 'primary', disabled, busy, testID, big,
56	}: { label: string; onPress: () => void; kind?: ButtonKind; disabled?: boolean; busy?: boolean; testID?: string; big?: boolean }) {
57	  const look: Record<ButtonKind, { bg: string; fg: string; border: string }> = {
58	    primary: { bg: colors.primary, fg: colors.primaryText, border: colors.primary },
59	    secondary: { bg: colors.chip, fg: colors.heading, border: colors.chip },
60	    danger: { bg: colors.bad, fg: '#FFF', border: colors.bad },
61	    accent: { bg: colors.accent, fg: colors.accentText, border: colors.accent },
62	    food: { bg: colors.foodBg, fg: colors.food, border: colors.foodBg },
63	    water: { bg: colors.waterBg, fg: colors.water, border: colors.waterBg },
64	    outlineDanger: { bg: colors.card, fg: colors.bad, border: colors.border },
65	  };
66	  const l = look[kind];
67	  return (
68	    <Pressable
69	      testID={testID}
70	      accessibilityRole="button"
71	      onPress={onPress}
72	      disabled={disabled || busy}
73	      style={({ pressed }) => [
74	        s.btn,
75	        big && s.btnBig,
76	        { backgroundColor: l.bg, borderColor: l.border, opacity: disabled ? 0.45 : pressed ? 0.8 : 1 },
77	      ]}
78	    >
79	      {busy ? <ActivityIndicator color={l.fg} /> : <Text style={[s.btnText, big && s.btnTextBig, { color: l.fg }]}>{label}</Text>}
80	    </Pressable>
81	  );
82	}
83	
84	export function Field({ label, ...props }: { label: string } & TextInputProps) {
85	  return (
86	    <View style={{ marginBottom: 10 }}>
87	      <Text style={s.label}>{label}</Text>
88	      <TextInput placeholderTextColor={colors.muted} style={s.input} {...props} />
89	    </View>
90	  );
91	}
92	
93	export function Toggle({ label, value, onChange }: { label: string; value: boolean; onChange: (v: boolean) => void }) {
94	  return (
95	    <View style={s.toggleRow}>
96	      <Text style={[s.body, { flex: 1 }]}>{label}</Text>
97	      <Switch
98	        value={value}
99	        onValueChange={onChange}
100	        accessibilityLabel={label}
101	        trackColor={{ true: colors.primary, false: colors.track }}
102	        thumbColor="#FFF"
103	      />
104	    </View>
105	  );
106	}
107	
108	export function ProgressBar({ value, color = colors.primary, track = colors.track }: { value: number; color?: string; track?: string }) {
109	  return (
110	    <View style={[s.track, { backgroundColor: track }]} accessibilityRole="progressbar" accessibilityValue={{ min: 0, max: 100, now: Math.round(value * 100) }}>
111	      <View style={[s.fill, { width: `${Math.round(value * 100)}%`, backgroundColor: color }]} />
112	    </View>
113	  );
114	}
115	
116	export function Banner({ kind, children }: { kind: 'info' | 'warn' | 'error' | 'good'; children: React.ReactNode }) {
117	  const bg = kind === 'warn' ? colors.warnBg : kind === 'error' ? colors.badBg : kind === 'good' ? colors.soft : colors.infoBg;
118	  const fg = kind === 'warn' ? colors.warn : kind === 'error' ? colors.bad : kind === 'good' ? colors.heading : colors.water;
119	  return (
120	    <View style={[s.banner, { backgroundColor: bg }]}>
121	      <Text style={{ color: fg, fontSize: 14 }}>{children}</Text>
122	    </View>
123	  );
124	}
125	
126	/** UC-4 "Show Maintenance Notice" — shown instead of a disabled module; the rest of the app keeps working (FR-5). */
127	export function MaintenanceNotice({ name }: { name: string }) {
128	  return (
129	    <Card>
130	      <Text style={s.cardTitle}>{name} is under maintenance</Text>
131	      <Text style={s.body}>
132	        This part of CometFit has been temporarily turned off by the developers. Everything else in the app still works.
133	        Please check back later.
134	      </Text>
135	    </Card>
136	  );
137	}
138	
139	export function Row({ children, style }: { children: React.ReactNode; style?: ViewStyle }) {
140	  return <View style={[{ flexDirection: 'row', alignItems: 'center', gap: 8, flexWrap: 'wrap' }, style]}>{children}</View>;
141	}
142	
143	/** Prototype stat: big number over a small grey label, left aligned (Activities "3 Workouts", Dashboard "18 Total visits"). */
144	export function Stat({ label, value, color }: { label: string; value: string; color?: string }) {
145	  return (
146	    <View style={s.stat}>
147	      <Text style={[s.statValue, color ? { color } : null]}>{value}</Text>
148	      <Text style={s.muted}>{label}</Text>
149	    </View>
150	  );
151	}
152	
153	// ---- TD-4 prototype pieces ---------------------------------------------------------------------------------------
154	
155	/** Initials for the header avatar ("SC" in the prototype). */
156	export function initials(name: string | null | undefined): string {
157	  const parts = (name ?? '').trim().split(/[\s._-]+/).filter(Boolean);
158	  if (parts.length === 0) return '?';
159	  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
160	  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
161	}
162	
163	export function Avatar({ name, size = 36 }: { name: string; size?: number }) {
164	  return (
165	    <View
166	      style={[s.avatar, { width: size, height: size, borderRadius: size / 2 }]}
167	      accessibilityLabel={`Signed in as ${name}`}
168	    >
169	      <Text style={[s.avatarText, { fontSize: size * 0.36 }]}>{initials(name)}</Text>
170	    </View>
171	  );
172	}
173	
174	/** Screen header: big green title, grey subtitle, initials avatar on the right (TD-4; every prototype screen). */
175	export function ScreenHeader({ title, subtitle, name, brand }: { title: string; subtitle?: string; name?: string; brand?: boolean }) {
176	  return (
177	    <View style={s.header}>
178	      {brand ? (
179	        <View style={s.headerTop}>
180	          <Text style={s.brand}>CometFit</Text>
181	          {name ? <Avatar name={name} /> : null}
182	        </View>
183	      ) : null}
184	      <View style={s.headerTop}>
185	        <View style={{ flex: 1 }}>
186	          <Text style={brand ? s.headline : s.title}>{title}</Text>
187	          {subtitle ? <Text style={s.subtitle}>{subtitle}</Text> : null}
188	        </View>
189	        {!brand && name ? <Avatar name={name} /> : null}
190	      </View>
191	    </View>
192	  );
193	}
194	
195	/** Small uppercase grey section label ("FRIENDS LEADERBOARD", "ACCOUNT & PREFERENCES"). */
196	export function SectionLabel({ children }: { children: React.ReactNode }) {
197	  return <Text style={s.sectionLabel}>{children}</Text>;
198	}
199	
200	/** Today / Week / Month pill switch (Food & Water prototype). */
201	export function Segmented<T extends string>({ options, value, onChange }: { options: { id: T; label: string }[]; value: T; onChange: (v: T) => void }) {
202	  return (
203	    <View style={s.segmented} accessibilityRole="tablist">
204	      {options.map((o) => {
205	        const on = o.id === value;
206	        return (
207	          <Pressable
208	            key={o.id}
209	            onPress={() => onChange(o.id)}
210	            accessibilityRole="tab"
211	            accessibilityState={{ selected: on }}
212	            style={[s.segment, on && s.segmentOn]}
213	            testID={`seg-${o.id}`}
214	          >
215	            <Text style={[s.segmentText, on && s.segmentTextOn]}>{o.label}</Text>
216	          </Pressable>
217	        );
218	      })}
219	    </View>
220	  );
221	}
222	
223	/** Settings-style row with a chevron (Account prototype). Tapping toggles an inline panel. */
224	export function ListRow({
225	  title, subtitle, open, onPress, danger, last, testID,
226	}: { title: string; subtitle?: string; open?: boolean; onPress: () => void; danger?: boolean; last?: boolean; testID?: string }) {
227	  return (
228	    <Pressable onPress={onPress} style={[s.listRow, last && !open ? null : s.listRowLine]} accessibilityRole="button" testID={testID}>
229	      <View style={{ flex: 1 }}>
230	        <Text style={[s.listRowTitle, danger ? { color: colors.bad } : null]}>{title}</Text>
231	        {subtitle ? <Text style={s.small}>{subtitle}</Text> : null}
232	      </View>
233	      <Text style={s.chevron}>{open ? '⌄' : '›'}</Text>
234	    </Pressable>
235	  );
236	}
237	
