content.content:
1	// CometFit mobile client (Expo / React Native; also runs in a browser for the demo — ASSUMPTIONS A-26).
2	// Deliverable 1 §5.3: client-server — this is the "Client (Mobile Application)"; every SD-1..SD-4 "Mobile App (View)"
3	// lifeline is one of the screens below. Developers get the "AdminDashboard (View)" of SD-4 instead.
4	// Look and navigation: spec/03-team-decisions/TD-4.md + spec/05-ui-prototype/ — five bottom tabs named
5	// Dashboard, Food & Water, Activities, Social, Account (TD-4 §1), features mapped onto them per TD-4 §2.
6	import { StatusBar } from 'expo-status-bar';
7	import React, { useCallback, useEffect, useState } from 'react';
8	import { Pressable, SafeAreaView, StyleSheet, Text, View } from 'react-native';
9	import { api, setToken, setUnauthorizedHandler } from './src/api';
10	import { isEnabled } from './src/logic';
11	import ActivityScreen from './src/screens/ActivityScreen';
12	import AdminDashboard from './src/screens/AdminDashboard';
13	import DashboardScreen from './src/screens/DashboardScreen';
14	import FriendsScreen from './src/screens/FriendsScreen';
15	import LoginScreen from './src/screens/LoginScreen';
16	import LogScreen from './src/screens/LogScreen';
17	import ProfileScreen from './src/screens/ProfileScreen';
18	import type { LoginResponse, ModuleState } from './src/types';
19	import { colors, MaintenanceNotice, ScreenHeader } from './src/ui';
20	
21	type Tab = 'dashboard' | 'food' | 'activities' | 'social' | 'account';
22	
23	// Titles and subtitles are the prototype's (spec/05-ui-prototype/2..6-*.png). The Dashboard mixes two modules
24	// (daily summary = NUTRITION, UREC check-in = ACTIVITY), so it is not guarded as a whole: each part shows its own
25	// maintenance notice (FR-5 "the rest of the app keeps working"; A-43).
26	const TABS: { id: Tab; label: string; title: string; subtitle: string; module?: string; moduleName?: string }[] = [
27	  { id: 'dashboard', label: 'Dashboard', title: 'Your effort adds up.', subtitle: 'One visit. One stronger day.' },
28	  { id: 'food', label: 'Food & Water', title: 'Food & Water', subtitle: 'Fuel your day. Stay hydrated.', module: 'NUTRITION', moduleName: 'Nutrition & Hydration' },
29	  { id: 'activities', label: 'Activities', title: 'Activities', subtitle: 'Make time for your next move.', module: 'ACTIVITY', moduleName: 'Activity & UREC Visits' },
30	  { id: 'social', label: 'Social', title: 'Social', subtitle: 'Small habits. Shared momentum.', module: 'SOCIAL', moduleName: 'Friends & Leaderboard' },
31	  { id: 'account', label: 'Account', title: 'Account', subtitle: 'Your profile, your preferences.' },
32	];
33	
34	const MODULE_POLL_MS = 15_000;
35	
36	export default function App() {
37	  const [session, setSession] = useState<LoginResponse | null>(null);
38	
39	  const logout = useCallback(async () => {
40	    try {
41	      await api.logout();
42	    } catch {
43	      /* session may already be gone */
44	    }
45	    setToken(null);
46	    setSession(null);
47	  }, []);
48	
49	  useEffect(() => {
50	    setUnauthorizedHandler(() => {
51	      setToken(null);
52	      setSession(null);
53	    });
54	    return () => setUnauthorizedHandler(null);
55	  }, []);
56	
57	  function loggedIn(r: LoginResponse) {
58	    setToken(r.token);
59	    setSession(r);
60	  }
61	
62	  return (
63	    <SafeAreaView style={styles.root}>
64	      <StatusBar style="dark" />
65	      {!session ? (
66	        <LoginScreen onLoggedIn={loggedIn} />
67	      ) : session.user.role === 'DEVELOPER' ? (
68	        <AdminDashboard onLogout={logout} name={session.user.displayName} />
69	      ) : (
70	        <StudentApp session={session} onLogout={logout} />
71	      )}
72	    </SafeAreaView>
73	  );
74	}
75	
76	function StudentApp({ session, onLogout }: { session: LoginResponse; onLogout: () => void }) {
77	  const [tab, setTab] = useState<Tab>('dashboard');
78	  const [modules, setModules] = useState<ModuleState[] | null>(null);
79	  const [refreshKey, setRefreshKey] = useState(0);
80	  const [name, setName] = useState(session.user.displayName);
81	
82	  // SD-4: Mobile App (Student) -> FeatureFlagService isEnabled(moduleId)
83	  useEffect(() => {
84	    let alive = true;
85	    const load = () => api.modules().then((m) => alive && setModules(m)).catch(() => undefined);
86	    load();
87	    const t = setInterval(load, MODULE_POLL_MS);
88	    return () => {
89	      alive = false;
90	      clearInterval(t);
91	    };
92	  }, [tab]);
93	
94	  const current = TABS.find((t) => t.id === tab)!;
