1	// Shapes returned by the CometFit server (see app/server controllers; classes from Deliverable 1 §5.2).
2	
3	export type Role = 'STUDENT' | 'DEVELOPER';
4	
5	export interface UserView {
6	  userId: number;
7	  username: string;
8	  displayName: string;
9	  role: Role;
10	  isPublic: boolean;
11	  permissions: string[];
12	}
13	export interface LoginResponse {
14	  token: string; expiresAt: string; user: UserView;
15	  // TD-1 (3): set when this device was just remembered
16	  deviceToken: string | null; trustedUntil: string | null; rememberedDevice: boolean;
17	}
18	export interface Registration { user: UserView; totpSecret: string; otpauthUri: string }
19	
20	export interface Profile {
21	  userId: number; username: string; displayName: string; email: string; role: Role; isPublic: boolean;
22	  calorieGoal: number | null; waterGoalMl: number | null; stepGoal: number | null; bottleSizeMl: number | null;
23	}
24	
25	export interface ModuleState { moduleId: 'NUTRITION' | 'ACTIVITY' | 'SOCIAL' | string; name: string; enabled: boolean }
26	
27	// UC-1
28	export type MealSource = 'MANUAL' | 'PHOTO' | 'DINING_MENU';
29	export interface MealEntry {
30	  entryId: number | null; foodName: string; calories: number; proteinG: number; carbsG: number; fatG: number;
31	  source: MealSource; diningItemId: number | null; loggedAt: string;
32	}
33	export interface MealEntryRequest {
34	  foodName?: string; calories?: number; proteinG?: number; carbsG?: number; fatG?: number;
35	  source: MealSource; diningItemId?: number;
36	}
37	export interface FoodEstimate { foodName: string; calories: number; proteinG: number; carbsG: number; fatG: number; confidence: number }
38	export interface PhotoEstimate { draft: MealEntry; foodItems: FoodEstimate[]; notice: string }
39	export interface DiningItem { itemId: number; name: string; location: string; calories: number; proteinG: number; carbsG: number; fatG: number }
40	// Water is stored in liters (team repo code LogWater.java); volumeMl is derived (class diagram WaterEntry.volumeMl).
41	export interface WaterEntry { entryId: number; amount: number; volumeMl: number; loggedAt: string }
42	export interface WaterSaveResult { saved: WaterEntry; summary: DailySummary; message: string }
43	export interface DailySummary {
44	  date: string; calories: number; calorieGoal: number; proteinG: number; carbsG: number; fatG: number;
45	  waterMl: number; waterLiters: number; waterGoalMl: number; bottleSizeMl: number; steps: number; stepGoal: number;
46	  latestHeartRate: number | null; mealCount: number; waterEntryCount: number; messages: string[];
47	}
48	export interface SaveResult<T> { saved: T; summary: DailySummary }
49	
50	// UC-2
51	export interface DeviceLink { linkId: number; deviceId: string; deviceType: string; platform: string; status: string; linkedAt: string }
52	export interface ActivityRecord { id: number; steps: number; heartRate: number | null; timestamp: string }
53	export interface PointTransaction { id: number; amount: number; reason: string; timestamp: string }
54	export interface PushStepsResult { record: ActivityRecord; stepsToday: number; stepGoal: number; pointsAwarded: PointTransaction | null; balance: number }
55	export interface RecVisit { visitId: number; readerId: string; timestamp: string }
56	export interface VisitResult { visit: RecVisit; pointsAwarded: PointTransaction | null; balance: number; message: string }
57	export interface VisitHistory { visits: RecVisit[]; visitsThisWeek: number; balance: number; transactions: PointTransaction[] }
58	
59	// UC-3
60	export type Relation = 'SELF' | 'FRIEND' | 'REQUEST_SENT' | 'REQUEST_RECEIVED' | 'NONE';
61	export interface PublicProfile {
62	  userId: number; username: string; displayName: string | null; isPublic: boolean; relation: Relation;
