1	// UC-1 Track Nutrition & Hydration — SD-1, all three alt branches plus water:
2	//   [Photo entry]       take photo -> submitMealPhoto(image) -> show estimate for review -> confirm / edit
3	//   [Dining menu item]  browse dining menu -> getMenu(location) -> menu list -> select item   (FR-8)
4	//   [Manual entry]      enter food name and calories                                           (FR-2)
5	//   then saveMealEntry(entry); "log water (bottle size / refill)" -> saveWaterEntry(volume)    (FR-6)
6	//   Water input in liters or gallons: team repo code LogWater.java (stage 2).
7	import * as ImagePicker from 'expo-image-picker';
8	import React, { useState } from 'react';
9	import { Platform, ScrollView, Text, View } from 'react-native';
10	import { api, ApiError } from '../api';
11	import { parseMacro, parsePositiveAmount, parsePositiveInt, progress, refillVolume, shortTime, toLiters } from '../logic';
12	import type { DailySummary, DiningItem, MealSource, PhotoEstimate } from '../types';
13	import { Banner, Button, Card, colors, Field, MaintenanceNotice, ProgressBar, Row, s } from '../ui';
14	import { useAsync } from '../useAsync';
15	
16	type Mode = 'MANUAL' | 'PHOTO' | 'DINING_MENU';
17	
18	export default function LogScreen({ onChanged }: { onChanged: () => void }) {
19	  const summaryQ = useAsync(() => api.summary(), []);
20	  const mealsQ = useAsync(() => api.meals(), []);
21	  const [mode, setMode] = useState<Mode>('MANUAL');
22	  const [msg, setMsg] = useState<{ kind: 'good' | 'error'; text: string } | null>(null);
23	
24	  if (summaryQ.error?.isMaintenance) return <MaintenanceNotice name="Nutrition & Hydration" />;
25	
26	  function saved(summary: DailySummary, text: string) {
27	    summaryQ.setData(summary);
28	    mealsQ.reload();
29	    setMsg({ kind: 'good', text });
30	    onChanged();
31	  }
32	  function failed(e: unknown) {
33	    setMsg({ kind: 'error', text: (e as ApiError).message });
34	  }
35	
36	  const sum = summaryQ.data;
37	  return (
38	    <ScrollView>
39	      {msg ? <Banner kind={msg.kind}>{msg.text}</Banner> : null}
40	      <WaterCard summary={sum} onSaved={saved} onError={failed} />
41	
42	      <Card title="Log a meal">
43	        <Row>
44	          {(['MANUAL', 'PHOTO', 'DINING_MENU'] as Mode[]).map((m) => (
45	            <View key={m} style={{ flex: 1, minWidth: 100 }}>
46	              <Button
47	                kind={mode === m ? 'primary' : 'secondary'}
48	                label={m === 'MANUAL' ? 'Manual' : m === 'PHOTO' ? 'Photo (AI)' : 'Dining menu'}
49	                onPress={() => setMode(m)}
50	              />
51	            </View>
52	          ))}
53	        </Row>
54	        {mode === 'MANUAL' ? <ManualMeal source="MANUAL" onSaved={saved} onError={failed} /> : null}
55	        {mode === 'PHOTO' ? <PhotoMeal onSaved={saved} onError={failed} /> : null}
56	        {mode === 'DINING_MENU' ? <DiningMenu onSaved={saved} onError={failed} /> : null}
57	      </Card>
58	
59	      <Card title="Today's meals">
60	        {sum ? (
61	          <Text style={s.muted}>
62	            {sum.calories} / {sum.calorieGoal} kcal · P {sum.proteinG} g · C {sum.carbsG} g · F {sum.fatG} g
63	          </Text>
64	        ) : null}
65	        {(mealsQ.data ?? []).length === 0 ? <Text style={s.muted}>No meals logged yet today.</Text> : null}
66	        {(mealsQ.data ?? []).map((m) => (
67	          <View key={m.entryId ?? m.loggedAt} style={s.listItem}>
68	            <Text style={s.body}>
69	              {m.foodName} — {m.calories} kcal
70	            </Text>
71	            <Text style={s.muted}>
72	              {sourceLabel(m.source)} · P {m.proteinG} g · C {m.carbsG} g · F {m.fatG} g · {shortTime(m.loggedAt)}
73	            </Text>
74	          </View>
75	        ))}
76	      </Card>
77	    </ScrollView>
78	  );
79	}
80	
81	function sourceLabel(src: MealSource) {
82	  return src === 'PHOTO' ? 'Photo' : src === 'DINING_MENU' ? 'UTD Dining' : 'Manual';
83	}
84	
85	type SavedFn = (s: DailySummary, text: string) => void;
86	type ErrFn = (e: unknown) => void;
87	
88	// ---- FR-6 water -----------------------------------------------------------------------------------------------
89	// Team repo code LogWater.enter(userId, amount, isLiter): the student can enter liters or gallons; the server stores
90	// liters truncated to two decimals and answers "Added 1.13L to Jane Doe". Refill buttons = Proposal §4 bottle refills.
91	function WaterCard({ summary, onSaved, onError }: { summary: DailySummary | null; onSaved: SavedFn; onError: ErrFn }) {
92	  const [custom, setCustom] = useState('');
93	  const [isLiter, setIsLiter] = useState(true);
94	  const [busy, setBusy] = useState(false);
95	  const bottle = summary?.bottleSizeMl ?? 500;
96	
97	  async function log(amount: number, liter: boolean) {
98	    setBusy(true);
99	    try {
100	      const r = await api.saveWaterEntry(amount, liter);
101	      onSaved(r.summary, r.message);
102	      setCustom('');
103	    } catch (e) {
104	      onError(e);
105	    } finally {
106	      setBusy(false);
107	    }
108	  }
109	  const customAmount = parsePositiveAmount(custom);
110	  const preview = customAmount !== null ? toLiters(customAmount, isLiter) : null;
111	  return (
112	    <Card title="Water">
113	      {summary ? (
114	        <>
115	          <Text style={s.body}>
116	            {summary.waterLiters.toFixed(2)} L ({summary.waterMl} / {summary.waterGoalMl} ml) today
117	          </Text>
118	          <ProgressBar value={progress(summary.waterMl, summary.waterGoalMl)} color="#2A8BD8" />
119	          {summary.waterMl < summary.waterGoalMl ? (
120	            <Banner kind="warn">Your water intake is low today. Refill your bottle!</Banner>
121	          ) : null}
122	        </>
123	      ) : null}
124	      <Row>
125	        <View style={{ flex: 1 }}>
126	          <Button label={`+1 refill (${bottle} ml)`} onPress={() => log(refillVolume(bottle, 1) / 1000, true)} busy={busy} testID="refill" />
127	        </View>
128	        <View style={{ flex: 1 }}>
129	          <Button kind="secondary" label={`+½ bottle (${refillVolume(bottle, 0.5)} ml)`} onPress={() => log(refillVolume(bottle, 0.5) / 1000, true)} disabled={busy} />
130	        </View>
131	      </Row>
132	      <Row>
133	        <View style={{ flex: 2 }}>
134	          <Field label={`Other amount (${isLiter ? 'liters' : 'gallons'})`} value={custom} onChangeText={setCustom} keyboardType="decimal-pad" testID="water-amount" />
135	        </View>
136	        <View style={{ flex: 1 }}>
137	          <Button kind={isLiter ? 'primary' : 'secondary'} label="L" onPress={() => setIsLiter(true)} testID="unit-liter" />
138	        </View>
139	        <View style={{ flex: 1 }}>
140	          <Button kind={!isLiter ? 'primary' : 'secondary'} label="gal" onPress={() => setIsLiter(false)} testID="unit-gallon" />
141	        </View>
142	      </Row>
143	      <Button
144	        label={preview !== null ? `Add ${preview} L` : 'Add'}
145	        onPress={() => customAmount !== null && log(customAmount, isLiter)}
146	        disabled={customAmount === null || busy}
147	        testID="water-add"
148	      />
149	      <Text style={s.muted}>Water is saved in liters (gallons are converted). Bottle size can be changed in Profile → Goals.</Text>
150	    </Card>
151	  );
152	}
153	
154	// ---- [Manual entry] (also used to confirm / edit a photo estimate) ---------------------------------------------
155	function ManualMeal({
156	  source, initial, onSaved, onError, onDone,
157	}: {
158	  source: MealSource;
159	  initial?: { foodName: string; calories: number; proteinG: number; carbsG: number; fatG: number };
160	  onSaved: SavedFn;
161	  onError: ErrFn;
162	  onDone?: () => void;
163	}) {
164	  const [name, setName] = useState(initial?.foodName ?? '');
165	  const [cal, setCal] = useState(initial ? String(initial.calories) : '');
166	  const [p, setP] = useState(initial ? String(round1(initial.proteinG)) : '');
167	  const [c, setC] = useState(initial ? String(round1(initial.carbsG)) : '');
168	  const [f, setF] = useState(initial ? String(round1(initial.fatG)) : '');
169	  const [busy, setBusy] = useState(false);
170	
171	  const calories = cal.trim() === '0' ? 0 : parsePositiveInt(cal, 5000);
172	  const macros = [parseMacro(p), parseMacro(c), parseMacro(f)];
173	  const valid = name.trim().length > 0 && calories !== null && macros.every((x) => x !== null);
174	
175	  async function save() {
176	    setBusy(true);
177	    try {
178	      const r = await api.saveMealEntry({
179	        source, foodName: name.trim(), calories: calories!, proteinG: macros[0]!, carbsG: macros[1]!, fatG: macros[2]!,
180	      });
181	      onSaved(r.summary, `Saved "${r.saved.foodName}" (${r.saved.calories} kcal).`);
182	      setName(''); setCal(''); setP(''); setC(''); setF('');
183	      onDone?.();
184	    } catch (e) {
185	      onError(e);
186	    } finally {
187	      setBusy(false);
188	    }
189	  }
190	
