1	// Small data-loading hook shared by the screens. Detects the server's MODULE_DISABLED answer so a screen can show
2	// the maintenance notice (FR-5; SD-4 "isEnabled(moduleId) -> false -> show maintenance notice").
3	import { useCallback, useEffect, useState } from 'react';
4	import { ApiError } from './api';
5	
6	export function useAsync<T>(fn: () => Promise<T>, deps: unknown[] = []) {
