          <Text style={s.body}>
            {summary.waterLiters.toFixed(2)} L ({summary.waterMl} / {summary.waterGoalMl} ml) today
          </Text>
          <ProgressBar value={progress(summary.waterMl, summary.waterGoalMl)} color="#2A8BD8" />
          {summary.waterMl < summary.waterGoalMl ? (
