1	// UC-3 View Friends' Progress — SD-3:
2	//   search username, send friend request -> sendRequest(targetId)          (UC-3 "Add / Accept Friend")
3	//   Friend: accept request -> acceptRequest(requestId)
4	//   Friend: choose fields to share -> setConsent(fields)                   (UC-3 "Set Data-Sharing Consent")
5	//   open Friends' Progress -> getFriendStats(friendId) -> consented stats only, leaderboard rank
6	//   plus "View Leaderboard", "Remove Friend"; FR-3 "search for a user and open their profile".
7	import React, { useState } from 'react';
8	import { ScrollView, Text, View } from 'react-native';
9	import { api, ApiError } from '../api';
10	import type { Consent, Friend, FriendStats, PublicProfile } from '../types';
11	import { Banner, Button, Card, colors, Field, MaintenanceNotice, Row, s, Stat, Toggle } from '../ui';
12	import { useAsync } from '../useAsync';
13	
14	export default function FriendsScreen({ me }: { me: number }) {
15	  const friendsQ = useAsync(() => api.friends(), []);
16	  const requestsQ = useAsync(() => api.requests(), []);
17	  const boardQ = useAsync(() => api.leaderboard(), []);
18	  const consentQ = useAsync(() => api.consent(), []);
19	  const [q, setQ] = useState('');
20	  const [results, setResults] = useState<PublicProfile[] | null>(null);
21	  const [profile, setProfile] = useState<PublicProfile | null>(null);
22	  const [stats, setStats] = useState<FriendStats | null>(null);
23	  const [msg, setMsg] = useState<{ kind: 'good' | 'error'; text: string } | null>(null);
24	
25	  if (friendsQ.error?.isMaintenance) return <MaintenanceNotice name="Friends & Leaderboard" />;
26	
27	  const err = (e: unknown) => setMsg({ kind: 'error', text: (e as ApiError).message });
28	  const reloadAll = () => {
29	    friendsQ.reload();
30	    requestsQ.reload();
31	    boardQ.reload();
32	  };
33	
34	  async function search() {
35	    try {
36	      setResults(await api.searchUsers(q));
37	      setProfile(null);
38	    } catch (e) {
39	      err(e);
40	    }
41	  }
42	  async function openProfile(id: number) {
43	    try {
44	      setProfile(await api.userProfile(id));
45	    } catch (e) {
46	      err(e);
47	    }
48	  }
49	  async function add(p: PublicProfile) {
50	    try {
51	      await api.sendRequest(p.userId);
52	      setMsg({ kind: 'good', text: `Friend request sent to ${p.username}.` });
53	      requestsQ.reload();
54	      if (results) setResults(await api.searchUsers(q));
55	      if (profile?.userId === p.userId) await openProfile(p.userId);
56	    } catch (e) {
57	      err(e);
58	    }
59	  }
60	  async function accept(requestId: number) {
61	    try {
62	      const f = await api.acceptRequest(requestId);
63	      setMsg({ kind: 'good', text: `You and ${f.username} are now friends.` });
64	      reloadAll();
65	    } catch (e) {
66	      err(e);
67	    }
68	  }
69	  async function decline(requestId: number) {
70	    try {
71	      await api.declineRequest(requestId);
72	      requestsQ.reload();
73	    } catch (e) {
74	      err(e);
75	    }
76	  }
77	  async function openStats(f: Friend | { userId: number }) {
78	    try {
79	      setStats(await api.friendStats(f.userId));
80	    } catch (e) {
81	      err(e);
82	    }
83	  }
84	  async function remove(f: Friend) {
85	    try {
86	      await api.removeFriend(f.userId);
87	      setStats(null);
88	      setMsg({ kind: 'good', text: `Removed ${f.username} from your friends.` });
89	      reloadAll();
90	    } catch (e) {
91	      err(e);
92	    }
93	  }
94	  async function saveConsent(c: Consent) {
95	    try {
96	      consentQ.setData(await api.setConsent(c));
97	      setMsg({ kind: 'good', text: 'Sharing settings saved.' });
98	    } catch (e) {
99	      err(e);
100	    }
101	  }
