1	// UC-2 Track Activity and Rec Center Visits — SD-2:
2	//   Connect and sync device: choose Connect Device -> request health permissions -> grant permission ->
3	//     linkDevice(deviceId) -> [server pairs] ; loop [periodic sync] pushSteps(steps, heartRate, timestamp)   (FR-4)
4	//   Rec center check-in: swipe student card -> recordVisit -> awardPoints -> "visit logged, points earned" ->
5	//     "show visit history and points"                                                                       (FR-7)
6	import React, { useEffect, useRef, useState } from 'react';
7	import { ScrollView, Text, View } from 'react-native';
8	import { api, ApiError } from '../api';
9	import { progress, shortTime } from '../logic';
10	import { FakeSmartDevice } from '../smartDevice';
11	import type { DeviceLink } from '../types';
12	import { Banner, Button, Card, colors, MaintenanceNotice, ProgressBar, Row, s, Stat, Toggle } from '../ui';
13	import { useAsync } from '../useAsync';
14	
15	const SYNC_EVERY_MS = 60_000;
16	
17	export default function ActivityScreen({ onChanged }: { onChanged: () => void }) {
18	  const devicesQ = useAsync(() => api.devices(), []);
19	  const recordsQ = useAsync(() => api.activityRecords(), []);
20	  const visitsQ = useAsync(() => api.visitHistory(), []);
21	  const summaryQ = useAsync(() => api.summary().catch(() => null), []);
22	  const [asking, setAsking] = useState(false);
23	  const [msg, setMsg] = useState<{ kind: 'good' | 'error' | 'info'; text: string } | null>(null);
24	  const [busy, setBusy] = useState<string | null>(null);
25	  const [autoSync, setAutoSync] = useState(false);
26	  const devicesRef = useRef<Record<string, FakeSmartDevice>>({});
27	
28	  const links = devicesQ.data ?? [];
29	
30	  function adapterFor(link: DeviceLink) {
31	    if (!devicesRef.current[link.deviceId]) {
32	      devicesRef.current[link.deviceId] = new FakeSmartDevice(link.deviceId, link.platform, link.linkId * 7919);
33	    }
34	    return devicesRef.current[link.deviceId];
35	  }
36	
37	  async function sync(link: DeviceLink, quiet = false) {
38	    const reading = adapterFor(link).readSinceLastSync();
39	    setBusy('sync');
40	    try {
41	      const r = await api.pushSteps({ deviceId: link.deviceId, steps: reading.steps, heartRate: reading.heartRate, timestamp: reading.timestamp });
42	      const pts = r.pointsAwarded ? ` Step goal reached: +${r.pointsAwarded.amount} points!` : '';
43	      if (!quiet || pts) setMsg({ kind: 'good', text: `Synced ${reading.steps} steps, ${reading.heartRate} bpm. ${r.stepsToday} steps today.${pts}` });
44	      recordsQ.reload();
45	      visitsQ.reload();
46	      summaryQ.reload();
47	      onChanged();
48	    } catch (e) {
49	      setMsg({ kind: 'error', text: (e as ApiError).message });
50	    } finally {
51	      setBusy(null);
52	    }
53	  }
54	
55	  // SD-2 loop [periodic sync]
56	  useEffect(() => {
57	    if (!autoSync || links.length === 0) return;
58	    const t = setInterval(() => links.forEach((l) => sync(l, true)), SYNC_EVERY_MS);
59	    return () => clearInterval(t);
60	    // eslint-disable-next-line react-hooks/exhaustive-deps
61	  }, [autoSync, links.map((l) => l.deviceId).join(',')]);
62	
63	  if (devicesQ.error?.isMaintenance) return <MaintenanceNotice name="Activity & UREC Visits" />;
64	
65	  async function grantAndLink(granted: boolean) {
66	    setAsking(false);
67	    if (!granted) {
68	      setMsg({ kind: 'info', text: 'Health permission was not granted, so no device was connected.' });
69	      return;
70	    }
71	    setBusy('link');
72	    const deviceId = `SIM-WATCH-${Math.floor(1000 + Math.random() * 9000)}`;
73	    try {
74	      const link = await api.linkDevice({ deviceId, deviceType: 'watch', platform: 'simulated', healthPermissionGranted: true });
