        <Banner kind="error">{summaryQ.error.message}</Banner>
      ) : sum ? (
        <Card title="Today" right={sum.date}>
          {sum.messages.map((m) => (
            <Banner key={m} kind={m.startsWith('Water goal reached') ? 'good' : 'warn'}>{m}</Banner>
